    #define TUNNEL 0

    /*
    ----------------------------------------------------------
    Loopless Concentric Discs!🟣🔴🟢 by Chronos
    ----------------------------------------------------------

        Another little doodle!
        This is probably well known, but I was playing with this idea and wanted to work it out for myself :)

        By setting the TUNNEL flag, the z-value is inverted and produces a tunnel effect.
        The resulting equation solve is probably equivalent to just doing 
        a translated ray-cylinder intersection (I'm guessing) ^_^'

    ----------------------------------------------------------
        Previous doodle: "Heimdal Rir Over Bivrost 🌌🌈🐎"
        https://www.shadertoy.com/view/lXKBzV
    ----------------------------------------------------------

        Derivation:
         The trick is to start with a cone equation to get centered concentric circles
         Then make a translation that *depends on z* z here is the depth or radius.
         The radius acts us an index to the circle, because it's different for each one.    

         z^2 = (x + az)^2 + (y + bz)^2
         z^2 = x^2 + 2*a*z*x + (az)^2 + y^2 + 2*b*z*y + (bz)^2
         z^2 = x^2 + y^2 + 2*(a*x + b*y)*z + ((a+b)*z)^2
           0 = x^2 + y^2 + 2*(a*x + b*y)*z + ((a+b)^2 - 1)*z^2

        solve by quadratic formula.

    ----------------------------------------------------------
    Self link: https://www.shadertoy.com/view/4XyfWV
    ----------------------------------------------------------
    */   

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float zoom = 2. + .75*sin(iTime*.1)+.5;
    vec2 uv = zoom * (2. * fragCoord - iResolution.xy)/iResolution.y;

    { // A little rot :)
        float c = cos(iTime/6.), s = sin(iTime/6.);
        uv*= mat2(c, s, -s, c);
    }

    vec3 color = vec3(0);

    const float PI = 3.141519265;
    float t = iTime * .5;
    vec2 v = vec2(cos(PI * t * .5), sin(PI * t)) * sqrt(2.)/2.;

    vec2 p = uv;

    float a = dot(v, v)-1.;
    float b = 2. * dot(v, p);
    float c = dot(p, p);

    // quadratic formula
    float discr = sqrt(b*b - 4. * a *c);
    vec2 Z = (-b + vec2(-1,1) * discr) / (2. * a);

    float z = max(Z.x, Z.y);

    #if TUNNEL
    float d = 1./z + iTime;
    #else
    float d = z + iTime;
    #endif

    float ps = length(fwidth(d));
    float fz = fract(d);
    float iz = floor(d);

    #if 0
    // Using golden ratio to get less periodic/repeating colors
    iz = fract(iz * (sqrt(5.)*.5 + .5)+.5) * 8.;
    #endif

    vec3 disc_col = .5 + .5*cos( 2. * PI * ((iz/8.)+vec3(0,1,2)/3.) ); // iq style palette

    color += mix(1., smoothstep(0., sqrt(z)*(.25 - fz*.25), fz), .5) * disc_col; // Disc, with shadow
    color += smoothstep(ps*2., .5*ps, min(fz, 1.- fz));                          // Circle

    #if TUNNEL
    color *= 1.-exp(-.5*z); // Fog color
    #endif

    // sRGB/Gamma, dither, and output! ^_^
    color = pow(color, vec3(1./2.2));
    color += (texelFetch(iChannel0, (ivec2(fragCoord)+iFrame*509)%1024, 0).rgb*2.-1.)/128.;
    fragColor = vec4(color, 1);
}
